package com.bdsbuddy.app;
import android.app.*; import android.os.*; import android.graphics.*; import android.view.*; import android.widget.*; import org.json.*; import java.text.*; import java.util.*;
public class MainActivity extends Activity {
 final String[] subjects={"Prosthodontics","Conservative Dentistry","Periodontology","Oral Surgery","Orthodontics","Pedodontics","Oral Medicine & Radiology","Public Health Dentistry"};
 final String[] types={"Lecture","Practical"}, statuses={"Present","Absent","Cancelled"}; ArrayList<JSONObject> entries=new ArrayList<>(); LinearLayout page; String date;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(35,45,65));if(bold)t.setTypeface(null,1);t.setPadding(dp(4),dp(5),dp(4),dp(5));return t;}
 public void onCreate(Bundle b){super.onCreate(b);date=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());load();render();}
 int[] count(String sub,String type){int p=0,n=0;for(JSONObject e:entries){if(!sub.equals(e.optString("subject")))continue;if(type!=null&&!type.equals(e.optString("type")))continue;String s=e.optString("status");if("Cancelled".equals(s))continue;n++;if("Present".equals(s))p++;}return new int[]{p,n};}
 String pct(int[] a){return a[1]==0?"—":String.format(Locale.getDefault(),"%.1f%%",100.0*a[0]/a[1]);}
 void render(){LinearLayout outer=new LinearLayout(this);outer.setPadding(dp(16),dp(12),dp(16),dp(12));outer.setOrientation(1);outer.setBackgroundColor(0xfff7f8fc);ScrollView sc=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(1);
 TextView h=label("BDS Buddy",28,true);h.setTextColor(0xff294b88);page.addView(h);page.addView(label("SRCDSR • 4th Year • 2026–27",14,false));page.addView(label("Roll No. S23-69  |  Clinical Batch F",13,false));
 int p=0,n=0;for(JSONObject e:entries){if("Cancelled".equals(e.optString("status")))continue;n++;if("Present".equals(e.optString("status")))p++;}page.addView(label("Overall attendance: "+(n==0?"—":String.format(Locale.getDefault(),"%.1f%%",100.0*p/n))+" ("+p+"/"+n+")\nTarget: 75% • Lecture + Practical combined",16,true));
 Button add=new Button(this);add.setText("+ Add individual lecture / practical");add.setOnClickListener(v->add());page.addView(add);Button pick=new Button(this);pick.setText("Choose date: "+date);pick.setOnClickListener(v->{Calendar c=Calendar.getInstance();new DatePickerDialog(this,(x,y,m,d)->{Calendar q=Calendar.getInstance();q.set(y,m,d);date=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(q.getTime());render();},c.get(1),c.get(2),c.get(5)).show();});page.addView(pick);
 page.addView(label("Subject-wise attendance",20,true));for(String s:subjects){int[] l=count(s,"Lecture"),r=count(s,"Practical"),a=count(s,null);page.addView(label(s,16,true));page.addView(label("Lecture: "+pct(l)+" ("+l[0]+"/"+l[1]+")   •   Practical: "+pct(r)+" ("+r[0]+"/"+r[1]+")",13,false));page.addView(label("Combined: "+pct(a)+" ("+a[0]+"/"+a[1]+")",13,true));}
 page.addView(label("Daily log • "+date,20,true));boolean found=false;for(int i=entries.size()-1;i>=0;i--){JSONObject e=entries.get(i);if(!date.equals(e.optString("date")))continue;found=true;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView t=label(e.optString("subject")+" • "+e.optString("type")+" • "+e.optString("status"),13,false);row.addView(t,new LinearLayout.LayoutParams(0,-2,1));Button del=new Button(this);del.setText("Delete");del.setOnClickListener(v->{entries.remove(e);save();render();});row.addView(del);page.addView(row);}if(!found)page.addView(label("No entries for this date yet.",14,false));page.addView(label("Cancelled classes are excluded from attendance totals.",12,false));sc.addView(page);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(outer);}
 void add(){LinearLayout box=new LinearLayout(this);box.setPadding(dp(12),dp(4),dp(12),dp(4));box.setOrientation(1);Spinner a=spinner(subjects),b=spinner(types),c=spinner(statuses);box.addView(a);box.addView(b);box.addView(c);new AlertDialog.Builder(this).setTitle("Add attendance").setView(box).setPositiveButton("Save",(d,w)->{JSONObject e=new JSONObject();try{e.put("date",date);e.put("subject",a.getSelectedItem().toString());e.put("type",b.getSelectedItem().toString());e.put("status",c.getSelectedItem().toString());entries.add(e);}catch(Exception ignored){}save();render();}).setNegativeButton("Cancel",null).show();}
 Spinner spinner(String[] items){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));return s;}
 void load(){try{JSONArray a=new JSONArray(getPreferences(0).getString("entries","[]"));for(int i=0;i<a.length();i++)entries.add(a.getJSONObject(i));}catch(Exception ignored){}}
 void save(){JSONArray a=new JSONArray();for(JSONObject e:entries)a.put(e);getPreferences(0).edit().putString("entries",a.toString()).apply();}
}
